INSERT INTO `article_entreprise` VALUES (4450,5,'RAID ECOHYGIENE','» RAID ECOHYGIENE  SARL\nرأسمالها : 100.000.00 درهم\nاملقر االجتماعي: العمارة 58 الشقة\nا3 زنقة واد سبو اكدال-الرباط -\nبمقتغضى  عقد  عرفي  بالرباط،\nبتاريخ  2025/12/01  قرر  شركاء\n»RAID ECOHYGIENE«  شركة\n: ش. ذ.م.م.» ما يلي\nتحويل  املقر االجتماعي  من\n«العمارة 58 الشقة ا3 زنقة واد سبو\nاكدال -الرباط - « الى « الشقة رقم 4\nزنقة الحسن الثاني رقم 6 - تمارة.\nبيع 500 حصة بقيمة 100 درهم\nللحصة بمبلغ 50.000.00 درهم من\nطرف السيدة كريمة الخراز لفائدة\nالسيد الياس رائد.\nتغيير الشكل القانوني للشركة من\n« شركة ذات مسؤولية محدودة « إلى\n« شركة ذات مسؤولية محدودة ذات\n.الشريك الوحيد\nتعديل القانون األسا؟سي\nتم  اإليداع  القانوني  باملحكمة\nبتاريخ\nبالرباط\nالتجارية\n2025/12/25 تحت رقم 198487','modification',0.443973,0.999436,'ner',NULL,'2026-05-14 08:49:02'),(4451,5,'CAFE PEDROCCHI','CAFE PEDROCCHI شركة\nSARL AU\nRC N°36051\nبمقتغضى  الجمع  العام  الغير\nالعادي  املنعقد  بتاريخ  29  أكتوبر\n2025 تقرر ما يلي :\n:تفويت كل حصص السيدة\nسميرة  البوعو؟سي1000  حصة\nبقيمة  100  درهم  للحصة  الواحدة\n.إلى السيد البشير امللقي\nاستقالة  واعفاء  املسيرة  السيدة\nسميرة  البوعو؟سي  وتعيين  السيد\n.البشير امللقي مسير ملدة غير محدودة\nتحديث  القانون  الداخلي  للشركة\nتم  اإليداع  القانوني  تحت  رقم\n47354   بتاريخ   18 ديسمبر 2025\n.لدى املحكمة االبتدائية بسال','cession',0.726577,0.999975,'ner',NULL,'2026-05-14 08:49:02'),(4452,5,'DELTA TOURS','DELTA TOURS\nشركة محدودة املسؤولية\nرأسمالها 400.000.00 درهم\nاملقر االجتماعي : 3 زنقة سيدي\nبنور، الطابق 4، الشقة رقم 20،\nالدارالبيضاء.\n700025/ :  RCالدارالبيضاء\nبمقتغضى  عقد  عرفي  بتاريخ  25\nنوفمبر 2025، قرر الشركاء لشركة\nشركة  محدودةDELTA TOURS\nاملسؤولية رأسمالها 400.000  درهم\nمقرها  االجتماعي  :  3  زنقة  سيدي\nبنور،  الطابق4  ،  الشقة  رقم  20،\nالدارالبيضاء التالي :\nنقل املقر االجتماعي إلى العنوان\nالتالي  :  بلوك  119  رقم  2  سيدي\nالسفلي،\nالطابق\nالبرنوطصي،\nالدارالبيضاء.\n. تحديث القوانين\nتم  اإليداع  القانوني  بكتابة\nالضبط  لدى  املحكمة  التجارية\nبالدارالبيضاء في  12 ديسمبر 2025\n.1002933 تحت عدد','modification',0.622169,0.999954,'ner',NULL,'2026-05-14 08:49:02'),(4453,5,'LA POULE QUI RIT','LA POULE QUI RIT شركة\nSARL AU\nتصفية الشركة\nمقرها االجتماعي: الشقة 3 الحي\nاإلداري تجزئة الشروق املدخل ب\n.الطابق الثاني خريبكة\n41003430 : الضريبة املهنية\nبمقتغضى  محضر  جمع  عام\nاستثنائي مؤرخ ب 24 ديسمبر 2025\n:بخريبكة تم االتفاق على ما يلي\nLA POULE QUI تصفية شركة\nRIT SARL AU\nتعيين السيد عبد الهادي املشبوح\nالحامل  للبطاقة  الوطنية  رقم\n. كمصفي للشركةQ331002\nاإليداع  القانوني:  وضع  ملف\nالشركة باملحكمة االبتدائية بخريبكة\nبتاريخ 26 ديسمبر 2025 تحت عدد\n.1771','liquidation',0.590818,0.999982,'ner',NULL,'2026-05-14 08:49:02'),(4454,5,'BTD BUILD','BTD BUILD SARL شركة\nمقرها االجتماعي: الشقة 3 الحي\nاإلداري تجزئة الشروق املدخل\n.بالطابق الثاني خريبكة\n41003542 : الضريبة املهنية\nبمقتغضى  محضر  جمع  عام\nاستثنائي مؤرخ ب 11 ديسمبر 2025\n:بخريبكة ثم االتفاق على ما يلي\nBTD BUILD حل مسبق لشركة\nSARL\nتعيين  السيد  بوكطيرة   محمد\nالحامل  للبطاقة  الوطنية  رقم\n. كمصفي للشركةQ245225\nاإليداع  القانوني:  وضع  ملف\nالشركة باملحكمة االبتدائية بخريبكة\nبتاريخ 26 ديسمبر 2025 تحت عدد\n.1771','liquidation',0.496976,0.999979,'ner',NULL,'2026-05-14 08:49:02'),(4455,5,'CONSAGRIAL','CONSAGRIAL SARL\nRC RABAT / 116489\nتغيرات قانونية\nبمقتغضى  عــقد  عرفـي  مؤرخ\nبالرباط، بـــتاريخ 12 شتنبر 2025 ،\nقرر الجمع العام ما يلي :\nخمسين  حصة  اجتماعية  (50)\nمن  طرف  السيد  محمد  بوجناح\n.لصالح السيد عادل مستنجد\nبموجب  القرار  السابق،  يصبح\nالشكل القانوني للشركة شركة ذات\nمسؤولية  محدودة  بدًالً  من  شركة\nذات  مسؤولية  محدودة  بشريك\n.وحيد\nتعيين  السيد  عادل  مستنجد\n.مسّيًّرًا ثاني للشركة ملدة غير محددة\nنقل املقر االجتماعي من العنوان\nالحالي  الكائن  بـ  17  شارع  األبطال،\nشقة 12، أكدال  الرباط، إلى العنوان\nالتالي:  شقة  26،  العمارة  43،  زنقة\n.أكوملان سيدي علي، أكدال  الرباط\nإضافة  األنشطة  التالية  إلى\nالغرض االجتماعي للشركة:\nإنجاز  دراسات  الجدوى  التقنية\nواالقتصادية؛\nوتتبع\nوالتصميم\nالهندسة\nاملشاريع  املتعلقة  باملجازر  وقاعات\nالتقطيع  واملنشآت  والصناعات\nالغذائية؛\nاول تتحمل اإلدارة أية مسؤولية فيما يتعلق بمضمون اإلعالنات.\nإعداد مخططات التهيئة والتوطين\nوإعادة التأهيل ومالءمة املنشآت مع\nاملعايير املعمول بها\nوالتقنية\nاإلدارية\nاملواكبة\nوالتنظيمية في قطاع املجازر والبنيات\nالتحتية للصناعات الغذائية؛\nإعداد  دفاتر  الشروط  الخاصة\n(CPS)  وملفات  االستشارة  وطلبات\nالعروض العمومية أو الخاصة؛\nتم  ااِلا يداع  القانوني  باملحكمة\nالتجارية بالرباط بتاريخ  25 ديسمبر\n2025  تحت رقم .198539','modification',0.590051,0.999987,'ner',NULL,'2026-05-14 08:49:02'),(4456,5,'QUATREFOIL CONSTRUCTION OF FUTUR','STE QUATREFOIL\nCONSTRUCTION OF\nFUTUR SARL AU\nقرر  الجمع  العام  االستثنائي\nاملنعقد في 14 نوفمبر .2025\nتصفية الشركة ذات مسؤولية-\nSTE\nQUATREFOIL\nمحدودة\nCONSTRUCTION OF FUTUR\nبشريك  وحيد  مقرSARL AU\nتصفيتها االجتماعي : رقم 10 تجزئة\n.اللة ميمونة الخميسات\nتم  اإليداع  بكتابة  الضبط\nباملحكمة  االبتدائية  بالخميسات\nتحت رقم 279  بتاريخ 11 ديسمبر\n.2025\nللنسخ و البيان\nالوكيل','liquidation',0.581792,0.99998,'ner',NULL,'2026-05-14 08:49:02'),(4457,5,'T GALLERY CORNICHE','T GALLERY CORNICHE\n.شركة ذات مسؤولية محدودة\nبرأس مال قدره 14.500.000 درهم\nاملقر الرئيؠسي : 22 شارع ماولي\nيوسف الطابق الرابع الدار البيضاء\nRC 577421\nرفع رأس مال الشركة\nبموجب  محضر  الجمع  العام\nاالستثنائي املنعقد بتاريخ 25 نوفمبر\n2025 ، تقرر ما يلي:\nالزياة  في  راسمال  الشركة  بمبلغ\n14.400.000  من  اجل  رفعه  من\n100.000  درهم  الى  14.500.000\nدرهم وذالك\nباصدار 144.000 حصة جديدة\nبقيمة  100  درهم  للحصة  الواحدة\nاكتتبت و حررة بالكامل باملقاصة مع\nالديون املستحقة في الحساب الجاري\nللشريك الشركة ثنور إيموبيلي بعدما\nتنازل الشركاء عن حقهم التفضيلي\nفي اإلكتتاب\nوشرع  بناء  على  ذالك  في  تعديل\nالفصل 6 و 7 من النظام األسا؟سي\nللشركة\nتحيين النظام األسا؟سي للشركة\nتم  اإليداع  القانوني  بكتابة\nالضبط  لدى  املحكمة  التجارية\nبالدار البيضاء، بـتـاريـخ  22 ديسمبر\n2025  تحت رقم 1004243','modification',0.719145,0.999982,'ner',NULL,'2026-05-14 08:49:02'),(4458,5,'T GALLERY 2','T GALLERY 2\nشركة ذات مسؤولية محدودة\nبرأ