INSERT INTO `article_mahakim` VALUES (113,5,NULL,'املحكمة االبتدائية التجارية\nبمراكش\nمكتب صعوبات املقاولة\nبفسخ مخطط اإلنقاذ شركة عبدو\nبولدينغ وبفتح مسطرة التصفية\nالقضائية\nملف رقم : 2025/8308/227\nإشعار\n2025/250 بمقتغضى الحكم عدد\n2025/12/23\nبتاريخ\nالصادر\nفي  ملف  صعوبات  املقاولة  عدد\nاملحكمة\n2025/8308/227\nاالبتدائية  التجارية  بمراكش  بفسخ\nمخطط  اإلنقاذ  وبفتح  مسطرة\nالتصفية  القضائية  في  حق  شركة\nعبدو  بولدينغ  املسجلة  بالسجل\nالتجاري  لدى  هذه  املحكمة  تحت\n.35295 عدد\nوبتحديد مدة التوقف عن الدفع\nفي ثمانية عشر شهرا السابقة لهذا\n.الحكم\nمع تعيين السيد يوسف بوهدون\nقاضيا منتدبا والسيد يوسف رابيعي\nنائبا له والسيد سعيد كرام سنديكا\nوالكائن : مجمع األحباس مركب كنوز\n- عمارة ا املكتب رقم 6 شارع عالل\n.الفا؟سي مراكش\nوعليه  فاملطلوب  من  الدائنين\nالتصريح  بديونهم  للسنديك  املعين\nضمن قائمة موقعة تتضمن املبالغ\nاملطلوبة مرفقة بالوثائق وذلك داخل\nأجل  شهرين  من  تاريخ  نشر  هذا\nاإلشعار  بالجريدة  الرسمية  طبقا\nملقتضيات املواد 584 و 719 و 720\nمن مدونة التجارة.\nيمدد هذا األجل بشهرين بالنسبة\nللدائنين  القاطنين  خارج  اململكة\n.املغربية\nرئيس كتابة الضبط','liquidation',NULL,'املحكمة االبتدائية',NULL,'2026-05-14 08:52:41'),(114,5,'معهد البشير','املحكمة االبتدائية التجارية بمراكش\nمكتب صعوبات املقاولة\nفتح مسطرة التسوية القضائية\nفي مواجهة شركة معهد البشير في\nشخص م.ق\nملف رقم : 2025/8302/248\nإشعار\n2025/245 بمقتغضى الحكم عدد\n2025/12/16\nبتاريخ\nالصادر\nفي  ملف  صعوبات  املقاولة  عدد\nقضت  املحكمة2025/8302/248\nاالبتدائية  التجارية  بمراكش  بفتح\nمسطرة  التسوية  القضائية  في  حق\nشركة معهد البشير املسجلة بالسجل\nالتجاري  لدى  املحكمة  االبتدائية\nالتجارية بمراكش تحت عدد .5927\nوتحديد تاريخ التوقف عن الدفع\nفي الثمانية عشر شهرا السابقة لهذا\n.الحكم\nمع تعيين السيد يوسف بوهدون\nقاضيا منتدبا والسيد يوسف رابيعي\nنائبا  له  والسيد  عبد  الغني  هبيل\nسنديكا الكائن 34 زنقة الحرية عمارة\nأ  ماولي  يوسف  الشقة  12  جليز\n.مراكش\nعليه  فاملطلوب  من  الدائنين\nالتصريح  بديونهم  للسنديك  املعين\nضمن قائمة موقعة تتضمن املبالغ\nاملطلوبة مرفقة بالوثائق وذلك داخل\nأجل  شهرين  من  تاریخ  نشر  هذا\nاإلشعار  بالجريدة  الرسمية  طبقا\nملقتضيات املواد 584 و 719 و 720\nمن مدونة التجارة .\nيمدد هذا األجل بشهرين بالنسبة\nللدائنين  القاطنين  خارج  اململكة\n.املغربية\nرئيس كتابة الضبط','taswiya_qadaiya',0.991733,'املحكمة االبتدائية',NULL,'2026-05-14 08:52:41'),(115,5,NULL,'املحكمة االبتدائية التجارية بمراكش\nمكتب صعوبات املقاولة\nفتح مسطرة التسوية القضائية\nفي مواجهة التاجرة «كريمة أيت\n»الكندافي\n2025/8302/223 : ملف عدد\nاشعار\n2025/244 بمقتغضى الحكم عدد\n2025/12/16\nبتاريخ\nالصادر\nفي  ملف  صعوبات  املقاولة  عدد\nقضت  املحكمة2025/8302/223\nاالبتدائية  التجارية  بمراكش  بفتح\nمسطرة  التسوية  القضائية  في  حق\nالتاجرة  «كريمة  أيت  الكندافي»،\nاملسجلة بالسجل التجاري املمسوك\nلدى  املحكمة  االبتدائية  بني  مالل\n.26460 : تحت عدد\nوبتحديد تاريخ التوقف عن الدفع\nفي الثمانية عشر شهر السابقة لهذا\nالحكم  مع  تعيين  السيد  يوسف\nبوهدون  قاضيا  منتدبا  والسيد\nيوسف  رابيعي  نائبا  عنه  والسيد\nمحمد  أمزيل  سنديكا  الكائن  شارع\nمحمد الخامس ص ب 10 تصومعت\nورزازات عليه فاملطلوب من الدائنين\nالتصريح  بديونهم  للسنديك  املعين\nضمن قائمة موقعة تتضمن املبالغ\nاملطلوبة مرفقة بالوثائق وذلك داخل\nأجل  شهرين  من  تاريخ  نشر  هذا\nاالشعار  بالجريدة  الرسمية  طبقا\nملقتضيات املواد 584 و 719 و 720\nمن مدونة التجارة .\nيمدد هذا األجل بشهرين بالنسبة\nللدائنين  القاطنين  خارج  اململكة\n.املغربية\nرئيس كتابة الضبط','taswiya_qadaiya',NULL,'املحكمة االبتدائية',NULL,'2026-05-14 08:52:42'),(116,5,'بيوتي','املحكمة االبتدائية التجارية بمراكش\nرقم امللف :  2025/125\n10420 : حساب عدد\nبيع أصل تجاري\nبمقتغضى  عقد  توثيقي  مؤرخ  في\n.  باعت  شركة  «س.م2025/12/04\nبيوتي»  شركة  ذات  املسؤولية\nاملحدودة  ذات  شريك  وحيد،\nرأسمالها  200.000  درهم،  الكائن\nمقرها  االجتماعي  بمراكش  املحاميد\nاملكتب  2  رقم  3  الطابق  األول  برج\nالزيتون لفائدة شركة «سارل ك ج م\nبيل انج باريس» شركة ذات املسؤولية\nاملحدودة، رأسمالها 100.000 درهم\nالكائن  مقرها  االجتماعي  بمراكش\nاملكتب  رقم  2  على  اليمين  الشقة\nرقم 6 زاوية شارع طارق بن زياد وابن\nعائشة إقامة اكسيل سيور العمارة\n.18\nجميع  األصل  التجاري  الكائن  بـ\nمراكش شارع محمد الخامس مركز\nتجاري کار إيدن رقم ب 210، املعد\nملؤسسة  للعناية  بالجمال،  واملقيد\nبالسجل التجاري تحت رقم (66943)\n.بجميع عناصره املادية واملعنوية\nبثمن  إجمالي  قدره  2.120.000\nدرهم، تم اإلبراء منه في العقد.\nفعلی  دائني  البائع  املذكور  أعاله\nأن  يتقدموا  بتعرضاتهم  إلى  قسم\nالسجل التجاري باملحكمة التجارية\nبمراكش داخل أجل يبتدئ من تاريخ\nنشر  اإلعالن  األول  وينتهي  في  اليوم\nالخامس عشر (15) من نشر اإلاعلن\n.الثاني\nالنشرة األولى\nرئيس مصلحة كتابة الضبط',NULL,0.999956,'املحكمة االبتدائية',NULL,'2026-05-14 08:52:42'),(117,5,'كونتوار دو بالتغ','املحكمة االبتدائية التجارية بمراكش\nتقديم أصل تجاري\n129/2025 : ملف عدد\n10450 : حساب عدد\nبمقتغضى  عقد  عرفي  مؤرخ  في\n19 نوفمبر 2025 ومسجل بمراكش\nبتاريخ 25 نوفمبر 2025 قدم السيد\nالكاملي  مصطفى  الحامل  لبطاقة\nالتعريف  الوطنية  رقم  285634 Y\nوالساكن  بتجزئة  املحاميد  7  رقم\n736 اسکجور مراکش.\nالشركة كونتوار دو بالتغ الكائن\nمقرها االجتماعي في تجزئة املحاميد\n7 رقم 736 مراكش في طور التأسيس\nجميع األصل التجاري الكائن بتجزئة\nاملحاميد 7 رقم 736 مراكش واملعد\nاستغالله  في  نشاط  عامل  االسقف\nالجبصية / مختص في الجبص\nواملسجل بالسجل التجاري بجميع\nعناصره املادية واملعنوية كحصة في\nشركة قوم بمبلغ 10.000 درهما\nفعلى  دائني  البائع  أن  يتقدموا\nبتصريحاتهم  إلى  قسم  السجل\nالتجاري باملحكمة التجارية بمراكش\nداخل  أجل  يبتدئ  من  تاريخ  نشر\nاإلعالن  األول  وينتهي  في  اليوم\nالخامس  عشر  من  نشر  اإلعالن\n.الثاني\nالنشرة األولى\nرئيس كتابة الضبط',NULL,0.99995,'املحكمة االبتدائية',NULL,'2026-05-14 08:52:42'),(118,5,NULL,'املحكمة االبتدائية التجارية بمراكش\nبيع أصل تجاري\nملف رقم : 130/2025\nحساب رقم : 10451\nأصل\nهبة\nعقد\nبمقتغضى\nتجاري  موثق  مؤرخ  في  فاتح\nديسمبر  2025  ومسجل  بمراكش\nبتاريخ\n2025/12/05،  تحت  عدد\nأمــــــــر\n2025-0125263-11071\nباستاخلص\n2025/112467، توصيل\n،  وهب  السيد20251205114009\nمحمد  ابرغو  الساكن  بمراكش\nتجزئة الزرقطوني رقم 857 املحاميد\nالحامل\nلبطاقة  التعريف  الوطنية\nرقم  10391   Eلفائدة  السيد  عبد\nالسالم  ابرغو  الساكن  بمراكش\nاالزدهار  2  رقم  392  االزدهار\nوالحامل  لبطاقة  التعريف  الوطنية\nرقم 150850.E\nجميع حصته من األصل التجاري\nاملتمثل  في  متجر  املستغل  بالعنوان\nالكائن بمراكش قسارية املالك باب\nفتوح  رقم  44-43  املخصص  لبيع\nمستلزمات الكهرباء واملقيد بالسجل\nالتجاري باملحكمة التجارية بمراكش\n.50168 تحت عدد\nبجميع عناصره املادية واملعنوية\nبثمن  قدره  ونهايته  مليون  درهم\n.1.000.000\nفعلى  دائني  األصل  التجاري\nاملذكور أعاله أن يتقدموا بتعرضاتهم\nإلى قسم السجل التجاري باملحكمة\nالتجارية بمراكش داخل أجل يبتدئ\nمن تاريخ نشر اإلعالن األول وينتهي في\nاليوم الخامس عشر من نشر اإلعالن\n.الثاني\nالنشرة األولى\nرئيس كتابة الضبط',NULL,NULL,'املحكمة االبتدائية',NULL,'2026-05-14 08:52:43'),(119,5,NULL,'املحكمة االبتدائية التجارية بمراكش\nبيع أصل تجاري\nملف رقم 131/2025\nحساب رقم 10453\nبمقتغضى عقدين عرفيين مؤرخين\nفي  2025/07/31  و  2025/08/05،\nبتاريخ\nبمراكش\nاملسجلين\n:  باعوا السادة2028/08/05\nالسيدة  عائشة  الخضيري  بنت\nعمر املزدادة بتاريخ 1950/01/01،\nالساكنة  برقم  58  درب  الجامع\nالروض  القديم،  الحاملة  للبطاقة\nالوطنية رقم 511605 Eصالحة إلى\n.2029/07/27 غاية\nالسيدة  سليمة  النجناوي  بنت\nاحمد املزدادة بتاريخ 1977/09/30،\nالساكنة  برقم  58  درب  الجامع\nالروض  القديم  مراكش  الحاملة\nللبطاقة  الوطنية  رقم  581019 E\n.2033/07/02 صالحة إلى غاية\nالسيدة  رجاء  النجناوي  بنت\nاحمد املزدادة بتاريخ 1975/10/12،\nالساكنة  برقم  58  درب  الجامع\nالروض  الجديد  مراكش  الحاملة\nللبطاقة  الوطنية  رقم  482538 E\n.2033/09/17 صالحة إلى غاية\nالسيد عبد الحق النجناوي املزداد\nبمراكش  بتاريخ  1962/06/19،\nمغربي  الجنسية  الساكن  رقم\n58  درب  الجامع  الروض  القديم\nمراكش  الحامل  للبطاقة  الوطنية\nرقم  168893  Eصالحة  إلى  غاية\n.2032/06/10\n)السيد محمد النجناوي (الحفيد\n،1982/10/28\nبتاريخ\nاملزداد\nالساكن  بقطاع  8  إقامة  حسناء\nعمارة أ شقة 15 النخيل حي الرياض\nالرباط  الحامل  للبطاقة  الوطنية\nرقم  36306  EEصالحة  إلى  غاية\n.2031/05/24\nالسيدة  نعيمة  النجناوي  بنت\nاحمد املزدادة بتاريخ 1956/06/21،\nالساكنة  ب  359  حي  أزلي  مراكش\nالحاملة  للبطاقة  الوطنية  رقم\nغاية\nإلى\nصالحة\nE551265\n.20